import { UseFormSetError, FieldValues, Path } from "react-hook-form";

interface ApiErrorResponse {
  message?: string;
  errors?: Record<string, string[] | string>;
}

interface CustomAxiosError {
  response?: {
    data?: ApiErrorResponse;
    status?: number;
  };
  message?: string;
}

export function handleServerValidationError<T extends FieldValues>(
  error: unknown,
  setError: UseFormSetError<T>,
  fieldMapping?: Record<string, string>
): void {
  const axiosError = error as CustomAxiosError;
  const resData = axiosError?.response?.data;
  if (resData && typeof resData === "object") {
    const errors = resData.errors;
    if (errors) {
      if (Array.isArray(errors)) {
        errors.forEach((errObj) => {
          if (errObj && typeof errObj === "object") {
            Object.entries(errObj).forEach(([backendKey, value]) => {
              let frontendKey = backendKey;
              if (fieldMapping && fieldMapping[backendKey]) {
                frontendKey = fieldMapping[backendKey];
              } else if (backendKey.includes(".")) {
                const baseKey = backendKey.split(".")[0];
                if (fieldMapping && fieldMapping[baseKey]) {
                  frontendKey = fieldMapping[baseKey];
                } else {
                  frontendKey = baseKey;
                }
              }
              const message = Array.isArray(value) ? value[0] : String(value);
              setError(frontendKey as Path<T>, {
                type: "server",
                message: message,
              });
            });
          }
        });
      } else if (typeof errors === "object") {
        Object.entries(errors).forEach(([backendKey, value]) => {
          let frontendKey = backendKey;
          if (fieldMapping && fieldMapping[backendKey]) {
            frontendKey = fieldMapping[backendKey];
          } else if (backendKey.includes(".")) {
            const baseKey = backendKey.split(".")[0];
            if (fieldMapping && fieldMapping[baseKey]) {
              frontendKey = fieldMapping[baseKey];
            } else {
              frontendKey = baseKey;
            }
          }
          const message = Array.isArray(value) ? value[0] : String(value);
          setError(frontendKey as Path<T>, {
            type: "server",
            message: message,
          });
        });
      }
    } else if (resData.message) {
      const msg = String(resData.message).toLowerCase();
      if (msg.includes("email")) {
        setError("email" as Path<T>, { type: "server", message: resData.message });
      } else if (msg.includes("username")) {
        setError("username" as Path<T>, { type: "server", message: resData.message });
      } else if (msg.includes("phone")) {
        setError("phone_number" as Path<T>, { type: "server", message: resData.message });
      } else if (msg.includes("password")) {
        setError("password" as Path<T>, { type: "server", message: resData.message });
      } else {
        setError("root" as Path<T>, { type: "server", message: resData.message });
      }
    }
  } else if (axiosError?.message) {
    setError("root" as Path<T>, { type: "server", message: axiosError.message });
  }
}

export function getErrorMessage(error: unknown): string {
  const axiosError = error as CustomAxiosError;
  const resData = axiosError?.response?.data;
  if (resData && typeof resData === "object") {
    const errors = resData.errors;
    if (errors) {
      if (Array.isArray(errors)) {
        return errors
          .map((errObj) => {
            if (errObj && typeof errObj === "object") {
              return Object.entries(errObj)
                .map(([key, val]) => `${Array.isArray(val) ? val.join(", ") : val}`)
                .join(", ");
            }
            return String(errObj);
          })
          .filter(Boolean)
          .join("; ");
      } else if (typeof errors === "object") {
        return Object.entries(errors)
          .map(([key, val]) => `${Array.isArray(val) ? val.join(", ") : val}`)
          .join("; ");
      }
    }
    if (resData.message) {
      return resData.message;
    }
  }
  return axiosError?.message || "An unexpected error occurred.";
}
